def transform(grid):
    H=len(grid); W=len(grid[0])
    # find separator: uniform nonzero row or column
    sep=None; axis=None
    for i,r in enumerate(grid):
        if len(set(r))==1 and r[0]!=0: sep=i; axis='h'; break
    if sep is None:
        for j in range(W):
            col=[grid[i][j] for i in range(H)]
            if len(set(col))==1 and col[0]!=0: sep=j; axis='v'; break
    if axis=='h':
        top=grid[:sep]; bot=grid[sep+1:]
        n=min(len(top),len(bot)); Wd=len(top[0])
        return [[2 if (top[i][j]!=0 and bot[i][j]!=0) else 0 for j in range(Wd)] for i in range(n)]
    else:
        left=[r[:sep] for r in grid]; right=[r[sep+1:] for r in grid]
        n=min(len(left[0]),len(right[0])); Hd=len(grid)
        return [[2 if (left[i][j]!=0 and right[i][j]!=0) else 0 for j in range(n)] for i in range(Hd)]

